package com.example.cvd;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.CompletableFuture;


import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import com.fasterxml.jackson.databind.node.*;
import java.time.Instant;
import java.util.*;

@EnabledIfEnvironmentVariable(named="CVD_EMAIL_TEST_DB",matches="jdbc:postgresql://localhost:15439/email_test")
class DummyApprovalDatabaseTest  {
 JdbcTemplate pg;DataStore db;AccessStore access;MetrologyApi api;Pipeline pipeline;KafkaTemplate<String,String> kafka;ObjectMapper mapper=new ObjectMapper();AccessSessions.Identity leader;
 void setup()throws Exception{var ds=new DriverManagerDataSource(System.getenv("CVD_EMAIL_TEST_DB"),"cvd","email-test");pg=new JdbcTemplate(ds);pg.execute("DROP SCHEMA public CASCADE;CREATE SCHEMA public;CREATE TABLE auth_bootstrap(id integer PRIMARY KEY);INSERT INTO auth_bootstrap VALUES(1)");access=new AccessStore(pg,new DataSourceTransactionManager(ds),"");access.initialize();pg.execute("CREATE TABLE commands(id text primary key,equipment_id text,body jsonb,status text)");db=new DataStore(pg,mapper,System.getenv("CVD_EMAIL_TEST_DB"),"cvd","email-test");pipeline=mock(Pipeline.class);kafka=mock(KafkaTemplate.class);api=new MetrologyApi(db,pipeline,access,kafka,true);api.init();leader=new AccessSessions.Identity(UUID.randomUUID().toString(),"fixture","Leader","EE",1);pg.update("INSERT INTO app_users(id,username,password_hash,role,department) VALUES(?::uuid,'fixture','unused','Leader','EE')",leader.id());actor(leader);}
 @AfterEach void close(){SecurityContextHolder.clearContext();org.springframework.web.context.request.RequestContextHolder.resetRequestAttributes();((com.zaxxer.hikari.HikariDataSource)db.ts.getDataSource()).close();}
 void actor(AccessSessions.Identity u){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of()));}
 ObjectNode event(boolean complete,String eq,String wafer,String run){var n=mapper.createObjectNode().put("equipmentId",eq).put("waferId",wafer).put("lotId","l1").put("sourceTime",Instant.now().plusSeconds(1).toString()).put("kind",complete?"process-result":"movement-complete");var p=n.putObject("payload").put("processRunId",run).put("slot",1).put("purpose","product").put("pm","PM1");if(complete){p.put("complete",true);var s=new MetrologyValidationTest().result().path("source").deepCopy();((ObjectNode)s).put("equipmentId",eq).put("waferId",wafer).put("processRunId",run);p.set("result",s);}else p.put("result","success").put("to","LP1");return n;}
 String create(String eq,String wafer,String run){api.evidence(event(true,eq,wafer,run).toString());api.evidence(event(false,eq,wafer,run).toString());return pg.queryForObject("SELECT id FROM metrology_runs WHERE source_key=?",String.class,MetrologyApi.key(eq,wafer,run));}
 long count(){return pg.queryForObject("SELECT count(*) FROM metrology_runs",Long.class);}
 ObjectNode result(String id,long seq,boolean review){var n=mapper.createObjectNode().put("equipmentId",MetrologyApi.STATION).put("eventId","event-"+id+"-"+seq).put("sequence",seq).put("kind","measurement-state");var p=n.putObject("payload").put("measurementId",id).put("state","completed");var r=new MetrologyValidationTest().result();r.set("source",api.detail(id).path("source"));if(review){r.put("defectQuality","review").put("quality","review");r.withArray("defects").addObject().put("defectId","d1").put("type","particle").put("x",0).put("y",0).put("sizeUm",2);}p.set("result",r);return n;}

 DummyApprovalApi approval;ObjectNode state;
 @BeforeEach void dummySetup()throws Exception{setup();var http=new org.springframework.mock.web.MockHttpServletRequest();http.setRequestURI("/api/equipment/"+Equipment.FIRST+"/maintenance/qualification");org.springframework.web.context.request.RequestContextHolder.setRequestAttributes(new org.springframework.web.context.request.ServletRequestAttributes(http));pg.execute("CREATE TABLE equipment_snapshot(id text primary key,body jsonb);CREATE TABLE equipment_connectivity(equipment_id text primary key,quality text)");approval=new DummyApprovalApi(db,access);approval.init();approval.init();state=mapper.createObjectNode().put("sourceTime",Instant.now().toString()).put("dummyApprovalModelVersion",1).put("recipeVersion","v1");var m=state.putObject("maintenance").put("id","maintenance1").put("generation",1).put("phase","ready");var run=m.putObject("run").put("id","qualification1").put("generation",1).put("recipeVersion","v1").put("lotId","l1").put("status","passed");var results=run.putObject("results");for(int i=1;i<=4;i++){String wafer="dummy"+i,process="process"+i;var e=event(true,Equipment.FIRST,wafer,process);((ObjectNode)e.path("payload")).put("purpose","dummy").put("pm","PM"+i);api.evidence(e.toString());api.evidence(event(false,Equipment.FIRST,wafer,process).toString());String id=pg.queryForObject("SELECT id FROM metrology_runs WHERE wafer_id=?",String.class,wafer);api.result(result(id,1,false).toString());var entry=results.putObject("PM"+i).put("waferId",wafer).put("complete",true);entry.putObject("result").put("processRunId",process).put("quality","pass");}save();actor(new AccessSessions.Identity(leader.id(),"fixture","Leader","PE",1));}
 void save(){pg.update("INSERT INTO equipment_snapshot VALUES(?,?::jsonb) ON CONFLICT(id) DO UPDATE SET body=excluded.body",Equipment.FIRST,state.toString());}
 ObjectNode request(String decision){return mapper.createObjectNode().put("requestId",UUID.randomUUID().toString()).put("decision",decision).put("reason","test evidence").put("digest",DummyApprovalApi.view(db,Equipment.FIRST,state).path("digest").asText());}
 @Test void qualificationAndAuthorization(){var v=DummyApprovalApi.view(db,Equipment.FIRST,state);assertTrue(v.path("canConfirm").asBoolean());var cmd=mapper.createObjectNode().put("equipmentId",Equipment.FIRST).put("type","resume");cmd.putObject("parameters");assertThrows(Exception.class,()->DummyApprovalApi.guard(db,cmd,state));var request=request("confirm");assertTrue(approval.decide(request).path("confirmed").asBoolean());approval.decide(request);assertEquals(1,pg.queryForObject("SELECT count(*) FROM dummy_confirmations",Integer.class));DummyApprovalApi.guard(db,cmd,state);assertEquals("qualification1",cmd.path("parameters").path("dummyApproval").path("runId").asText());assertEquals("ready",state.path("maintenance").path("phase").asText());for(String dept:List.of("EE","PE"))for(String role:List.of("Operator","Engineer","Leader")){actor(new AccessSessions.Identity(leader.id(),"fixture",role,dept,1));if(dept.equals("PE")&&!role.equals("Operator"))assertDoesNotThrow(DummyApprovalApi::authorize);else assertThrows(Exception.class,DummyApprovalApi::authorize);}}
 @Test void replacedMeasurementAndRecipeInvalidate(){approval.decide(request("confirm"));String id=pg.queryForObject("SELECT id FROM metrology_runs WHERE wafer_id='dummy1'",String.class);String next=api.remeasure(id,Map.of("requestId",UUID.randomUUID().toString())).get("id");assertFalse(DummyApprovalApi.view(db,Equipment.FIRST,state).path("confirmed").asBoolean());api.result(result(next,1,false).toString());assertTrue(DummyApprovalApi.view(db,Equipment.FIRST,state).path("canConfirm").asBoolean());state.put("recipeVersion","v2");assertFalse(DummyApprovalApi.view(db,Equipment.FIRST,state).path("canConfirm").asBoolean());}
 @Test void fleetQualificationIsIsolated(){var list=new FleetApi(db).list();assertEquals("awaiting-pe",((com.fasterxml.jackson.databind.JsonNode)list.getFirst().get("maintenance")).path("qualificationStatus").asText());assertTrue(((com.fasterxml.jackson.databind.JsonNode)list.get(1).get("maintenance")).isMissingNode());approval.decide(request("confirm"));assertEquals("approved",((com.fasterxml.jackson.databind.JsonNode)new FleetApi(db).list().getFirst().get("maintenance")).path("qualificationStatus").asText());}
 @Test void missingAndRejectAndPendingResume(){pg.update("DELETE FROM metrology_runs WHERE wafer_id='dummy4'");assertFalse(DummyApprovalApi.view(db,Equipment.FIRST,state).path("canConfirm").asBoolean());assertThrows(Exception.class,()->approval.decide(request("confirm")));assertEquals("rejected",approval.decide(request("reject")).path("status").asText());assertThrows(Exception.class,()->approval.decide(request("confirm")));pg.update("INSERT INTO commands VALUES('pending',?,?::jsonb,'received')",Equipment.FIRST,"{\"type\":\"resume\"}");String id=pg.queryForObject("SELECT id FROM metrology_runs WHERE wafer_id='dummy1'",String.class);assertThrows(Exception.class,()->api.remeasure(id,Map.of("requestId",UUID.randomUUID().toString())));}
}
